    static ServerMatch game(){return GeneratedRuleBatch28Test.fixture(config());}
    static CardInstance prize(ServerMatch m,UUID p,int slot,String id){var hand=PairedTrainerPlayTest.zone(m,p,"hand");var card=hand.stream().filter(x->x.definitionId().equals(id)).findFirst().orElseThrow();hand.remove(card);hand.add(PairedTrainerPlayTest.zone(m,p,"prizes").set(slot,card));return card;}
