    public static void main(String[] args){coins();privateAndDecline();exclusive();multiple();direct();directLucky();locks();concession();suspendedTrainerConcession();ai();schema();System.out.println("NonPokemonBatch128Test passed: Greedy Dice both players/coin outcomes, decline/privacy/authentication, face-up/Checkup/final-Prize exclusions, chains and simultaneous Lucky Bonus order, direct-Prize continuation/counts/final win, hand locks and hand-play history, concession conservation and four AI levels");}
    static void coins(){for(UUID p:List.of(A,B)){var sides=new HashSet<Boolean>();for(int advance=0;advance<32&&sides.size()<2;advance++){
        var m=game();if(p.equals(B))m.endTurn(A);var card=prize(m,p,0,"trainer");prize(m,p,1,"energy");for(int i=0;i<advance;i++)m.flipCoinsByEffect(p,1);m.attack(p,"hit");m.takePrizeAt(p,0);int rng=m.randomTranscript().size();choose(m,p,0);boolean heads=m.phase()==MatchPhase.PRIZE_SELECTION;sides.add(heads);check(m.randomTranscript().size()==rng+1&&m.privateView(p).discard().contains(card)&&!m.privateView(p).hand().contains(card),"Dice wrong coin count/disposal");if(heads){check(m.pendingChoicePlayer().equals(p),"Bonus wrong owner");m.takePrizeAt(p,0);}check(m.privateView(p).prizes().size()==(heads?4:5),"Wrong extra Prize count");NonPokemonBatch103Test.settle(m);
    }check(sides.size()==2,"Missing coin side for "+p);}}
    static void privateAndDecline(){var m=aiGame(IDS.getFirst());var q=m.effectChoicePrompt(A);var before=m.clientView(A);var rng=m.randomTranscript();reject(()->m.effectChoicePrompt(B));reject(()->m.chooseEffectOption(B,q.resolutionId(),0,0));reject(()->m.chooseEffectOption(A,UUID.randomUUID(),0,0));reject(()->m.chooseEffectOption(A,q.resolutionId(),1,0));reject(()->m.chooseEffectOption(A,q.resolutionId(),0,2));reject(()->m.takePrizeAt(A,0));reject(()->m.endTurn(A));check(before.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"Invalid request mutated Prize window");int held=m.privateView(A).hand().size();choose(m,A,1);check(m.privateView(A).hand().size()==held+1&&rng.equals(m.randomTranscript()),"Decline flipped a coin or lost card");reject(()->m.chooseEffectOption(A,q.resolutionId(),0,0));NonPokemonBatch103Test.settle(m);}
    static void exclusive(){
        var m=game();var card=DynamicPassiveModifierTest.hand(m,A,"trainer");check(!m.canPlayTrainer(A,card.instanceId(),null),"Dice playable from hand");reject(()->m.playTrainer(A,card.instanceId(),null));
        for(String mode:List.of("faceup","checkup","last")){var n=game();var c=prize(n,A,0,"trainer");if(mode.equals("faceup"))NonPokemonBatch116Test.faces(n,A).add(c.instanceId());if(mode.equals("last"))GeneratedRuleBatch47Test.remainingPrizes(n,1);if(mode.equals("checkup")){NonPokemonBatch75Test.hurt(n,B,n.activePokemonView(B).pokemonId(),990);n.applySpecialConditionByEffect(A,B,SpecialCondition.POISONED);n.endTurn(A);}else n.attack(A,"hit");int rng=n.randomTranscript().size();n.takePrizeAt(A,0);check(!n.hasPendingEffectChoice()&&n.privateView(A).hand().contains(c)&&n.randomTranscript().size()==rng,"Illegal Prize window "+mode);if(mode.equals("last"))check(n.phase()==MatchPhase.FINISHED,"Last Prize did not win");else NonPokemonBatch103Test.settle(n);}
    }
    static void multiple(){for(int first:List.of(0,1)){var c=config();c.defenderPrizes=2;c.ownAbility=NonPokemonBatch2Test.DATA.pokemon("sv3-5_en_113").orElseThrow().ability("lucky-bonus").orElseThrow();var m=GeneratedRuleBatch28Test.fixture(c);var dice=prize(m,A,0,"trainer");var lucky=prize(m,A,1,"attacker");m.attack(A,"hit");m.takePrizeAt(A,0);check(!m.hasPendingEffectChoice(),"First simultaneous Prize revealed early");m.takePrizeAt(A,0);choose(m,A,first);if(first==0)choose(m,A,1);else m.decideLuckyBonus(A,false);if(first==0)m.decideLuckyBonus(A,false);else choose(m,A,1);check(m.privateView(A).hand().containsAll(List.of(dice,lucky)),"Selected mixed Prize order lost card");NonPokemonBatch103Test.settle(m);}
        var outcomes=new HashSet<Integer>();for(int advance=0;advance<32;advance++){var m=game();var first=prize(m,A,0,"trainer");var second=prize(m,A,1,"trainer");prize(m,A,2,"energy");for(int i=0;i<advance;i++)m.flipCoinsByEffect(A,1);m.attack(A,"hit");m.takePrizeAt(A,0);choose(m,A,0);int used=1;if(m.phase()==MatchPhase.PRIZE_SELECTION){m.takePrizeAt(A,0);check(m.hasPendingEffectChoice(),"Extra Prize Dice did not open its own window");choose(m,A,0);used++;if(m.phase()==MatchPhase.PRIZE_SELECTION)m.takePrizeAt(A,0);}outcomes.add(m.privateView(A).prizes().size());check(m.privateView(A).discard().contains(first)&&m.privateView(A).discard().contains(second)==(used==2),"Chained Dice disposal wrong");NonPokemonBatch103Test.settle(m);if(outcomes.containsAll(Set.of(3,4,5)))break;}check(outcomes.containsAll(Set.of(3,4,5)),"Chains lack HH/HT/T coverage");
    }
    static AttackDefinition directAttack(){return DeckDiscardTriggeredAbilityTest.attack(0,"{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":2},{\"type\":\"take_prize_cards\",\"target\":\"SELF\",\"amount\":2,\"bind\":\"taken\"},{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":3}");}
    static void direct(){for(boolean use:List.of(false,true)){var c=config();c.attack=directAttack();var m=GeneratedRuleBatch28Test.fixture(c);var dice=prize(m,A,0,"trainer");var ordinary=prize(m,A,1,"energy");prize(m,A,2,"energy");int held=m.privateView(A).hand().size(),turn=m.turnNumber();m.attack(A,c.attack.id());check(m.privateView(A).hand().size()==held+2,"Prefix failed");GeneratedRuleBatch47Test.take(m,A,0);check(m.privateView(A).hand().size()==held+2,"Direct first Prize entered hand early");GeneratedRuleBatch47Test.take(m,A,0);check(m.phase()==MatchPhase.PRIZE_SELECTION&&m.privateView(A).hand().contains(ordinary)&&!m.privateView(A).hand().contains(dice),"Direct window did not stage");choose(m,A,use?0:1);boolean bonus=m.phase()==MatchPhase.PRIZE_SELECTION;if(bonus)m.takePrizeAt(A,0);NonPokemonBatch103Test.settle(m);check(m.currentPlayer().equals(B)&&m.turnNumber()==turn+1&&m.privateView(A).hand().size()==held+5+1+(use?0:1)+(bonus?1:0),"Direct prefix/tail repeated or skipped");check(turnPrizes(m,A,"previousTurnPrizesTaken")==2+(bonus?1:0),"Direct Prize count missing");}
        var c=config();c.attack=directAttack();var m=GeneratedRuleBatch28Test.fixture(c);var dice=prize(m,A,0,"trainer");prize(m,A,1,"energy");GeneratedRuleBatch47Test.remainingPrizes(m,2);int held=m.privateView(A).hand().size();m.attack(A,c.attack.id());GeneratedRuleBatch47Test.take(m,A,0);GeneratedRuleBatch47Test.take(m,A,0);check(m.phase()==MatchPhase.FINISHED&&m.privateView(A).hand().size()==held+4&&m.privateView(A).hand().contains(dice)&&!m.hasPendingEffectChoice(),"Final direct Prize executed optional card/tail");
    }
    static int turnPrizes(ServerMatch m,UUID p,String name){try{var f=ServerMatch.class.getDeclaredField("players");f.setAccessible(true);var player=((Map<?,?>)f.get(m)).get(p);var v=player.getClass().getDeclaredField(name);v.setAccessible(true);return v.getInt(player);}catch(Exception e){throw new AssertionError(e);}}
    static void directLucky(){var c=config();c.attack=directAttack();c.ownAbility=NonPokemonBatch2Test.DATA.pokemon("sv3-5_en_113").orElseThrow().ability("lucky-bonus").orElseThrow();var m=GeneratedRuleBatch28Test.fixture(c);var lucky=prize(m,A,0,"attacker");prize(m,A,1,"energy");m.attack(A,c.attack.id());GeneratedRuleBatch47Test.take(m,A,0);GeneratedRuleBatch47Test.take(m,A,0);check(m.hasPendingLuckyBonus(A),"Direct prize did not activate Lucky Bonus");m.decideLuckyBonus(A,false);check(m.privateView(A).hand().contains(lucky)&&!m.hasPendingEffectChoice()&&m.currentPlayer().equals(B),"Direct Lucky Bonus failed to resume attack");}
    static void locks(){var c=config();c.defenderAttack=DeckDiscardTriggeredAbilityTest.attack(0,TrainerPlayLockTest.lock("ITEM")+",{\"type\":\"trainer_attempt_coin_gate\",\"target\":\"OPPONENT_ACTIVE\",\"scope\":\"PLAYER\",\"source\":\"HAND\",\"on_tails\":\"DISCARD_INSTEAD_OF_USE\",\"duration\":\"OPPONENT_NEXT_TURN\"}");var m=GeneratedRuleBatch28Test.fixture(c);m.endTurn(A);m.attack(B,c.defenderAttack.id());var dice=prize(m,A,0,"trainer");prize(m,A,1,"energy");check(m.trainerPlayLocked(A,"trainer"),"Lock fixture");int history=GeneratedRuleBatch53Test.history(m,"handPlays").size();m.attack(A,"hit");m.takePrizeAt(A,0);int rng=m.randomTranscript().size();choose(m,A,0);check(m.privateView(A).discard().contains(dice)&&m.randomTranscript().size()==rng+1&&GeneratedRuleBatch53Test.history(m,"handPlays").size()==history,"Prize Item incorrectly used hand lock/coin gate/history");if(m.phase()==MatchPhase.PRIZE_SELECTION)m.takePrizeAt(A,0);NonPokemonBatch103Test.settle(m);}
    static void concession(){for(boolean direct:List.of(false,true)){var c=config();if(direct)c.attack=directAttack();var m=GeneratedRuleBatch28Test.fixture(c);var dice=prize(m,A,0,"trainer");prize(m,A,1,"energy");m.attack(A,c.attack.id());if(direct){GeneratedRuleBatch47Test.take(m,A,0);GeneratedRuleBatch47Test.take(m,A,0);}else m.takePrizeAt(A,0);m.concede(B);check(m.privateView(A).hand().contains(dice)&&!m.hasPendingEffectChoice()&&!m.hasPendingPrizeTakeSelection(),"Concession lost pending Dice/resume");}}
