    static void ai(){for(var level:AiDifficulty.values()){var m=aiGame(IDS.getFirst());var s=MatchSession.multiplayer(m,A,B);AiCardOperationTest.settle(s,level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"AI stalled "+level);var c=config();c.attack=directAttack();var n=GeneratedRuleBatch28Test.fixture(c);prize(n,A,0,"trainer");prize(n,A,1,"energy");n.attack(A,c.attack.id());var session=MatchSession.multiplayer(n,A,B);AiCardOperationTest.settle(session,level);AiCardOperationTest.finish(session,level);check(n.phase()==MatchPhase.FINISHED,"Direct AI stalled "+level);}}
